/**
 * A readable label for a forum route: FastRoute patterns like `/d/{id:\d+(?:-[^/]*)?}[/{near:[^/]*}]`
 * become `/d/:id`.
 */
export default function routeLabel(route) {
  const path = route.path.replace(/\{(\w+)(?::[^{}]*)?\}/g, ':$1').replace(/\[[^[\]]*\]/g, '');
  return `${route.name} — ${path || '/'}`;
}
flarum.reg.add('fof-scavenger-hunt', 'forum/utils/routeLabel', routeLabel);