import app from 'flarum/forum/app';
import routeLabel from '../utils/routeLabel';
import Component from 'flarum/common/Component';
import Select from 'flarum/common/components/Select';

/** A Location's saved attributes. */

/** The field values: an empty route means any page, an empty item any item. */

export const ANY = '';
export function locationValue(fields, spots) {
  const contextType = spots.find(candidate => candidate.id() === fields.spot())?.contextType() ?? null;
  return {
    spot: fields.spot(),
    route: fields.route() || null,
    contextType,
    contextId: contextType && fields.contextId() ? Number(fields.contextId()) : null
  };
}

/**
 * The spot, page and item pickers for a Location.
 */
export default class LocationFields extends Component {
  view() {
    const {
      fields,
      spots,
      routes
    } = this.attrs;
    const spot = spots.find(candidate => candidate.id() === fields.spot());
    const spotOptions = {};
    spots.forEach(candidate => spotOptions[candidate.id()] = candidate.label());
    const routeOptions = {
      [ANY]: app.translator.trans('fof-scavenger-hunt.forum.dashboard.locations.any_page', {}, true)
    };
    routes.filter(route => !spot || spot.allowsRoute(route.name)).forEach(route => routeOptions[route.name] = routeLabel(route));
    return [m("div", {
      className: "LocationRow-field"
    }, m("label", null, app.translator.trans('fof-scavenger-hunt.forum.dashboard.locations.spot')), m(Select, {
      options: spotOptions,
      value: fields.spot(),
      onchange: value => fields.spot(value)
    })), m("div", {
      className: "LocationRow-field"
    }, m("label", null, app.translator.trans('fof-scavenger-hunt.forum.dashboard.locations.page')), m(Select, {
      options: routeOptions,
      value: fields.route(),
      onchange: value => fields.route(value)
    })), spot?.contextType() && m("div", {
      className: "LocationRow-field"
    }, m("label", null, app.translator.trans('fof-scavenger-hunt.forum.dashboard.locations.item', {
      type: spot.contextType()
    })), m("input", {
      className: "FormControl",
      type: "number",
      min: "1",
      value: fields.contextId(),
      oninput: e => fields.contextId(e.target.value),
      placeholder: app.translator.trans('fof-scavenger-hunt.forum.dashboard.locations.any_item', {}, true)
    }))];
  }
}
flarum.reg.add('fof-scavenger-hunt', 'forum/dashboard/LocationFields', LocationFields);